# Create an empty dictionary to store student grades
student_grades = {}

def add_student(name):
    """Add a student to the dictionary with an empty list of grades."""
    if name not in student_grades:
        student_grades[name] = []

def add_grade(name, grade):
    """Add a grade to a student's list of grades."""
    student_grades[name].append(grade)

def calculate_average(name):
    """Calculate the average grade of a student."""
    if name in student_grades:
        return sum(student_grades[name]) / len(student_grades[name])
    else:
        return "Student not found."

# Sample Input: add_student('John'), add_grade('John', 90), add_grade('John', 80), calculate_average('John')
add_student('John')
add_grade('John', 90)
add_grade('John', 80)
print(calculate_average('John'))  # Output: 70.0
```

This script defines three functions: `add_student`, `add_grade`, and `calculate_average`. The `add_student` function adds a new student to the dictionary with an empty list of grades. The `add_grade` function adds a grade to a student's list of grades. The `calculate_average` function calculates the average grade of a student by summing all their grades and dividing by the number of grades. The function returns the average grade or an error message if the student is not found.
